#include <iostream>
using namespace std;

int main() {
    // Whole number: 4 bytes on stack
    int age = 25;

    // Decimal number: 4 bytes on stack
    float price = 9.99f;

    // Single character: 1 byte on stack
    char grade = 'A';

    // True/false: 1 byte on stack
    bool passed = true;

    cout << "Age:    " << age    << endl;
    cout << "Price:  " << price  << endl;
    cout << "Grade:  " << grade  << endl;
    cout << "Passed: " << passed << endl;

    // sizeof shows byte size at compile time
    cout << "sizeof(int)   = " << sizeof(int)   << endl;
    cout << "sizeof(float) = " << sizeof(float) << endl;
    cout << "sizeof(char)  = " << sizeof(char)  << endl;
    cout << "sizeof(bool)  = " << sizeof(bool)  << endl;

    return 0;
}

